package com.medtrack.transfer.service; import com.medtrack.inventory.dto.*; import com.medtrack.inventory.service.FefoAllocationEngine; import com.medtrack.medicine.entity.*; import com.medtrack.medicine.repository.MedicineRepository; import com.medtrack.shared.exception.*; import com.medtrack.transfer.dto.*; import com.medtrack.transfer.entity.*; import com.medtrack.transfer.repository.*; import com.medtrack.user.entity.User; import com.medtrack.user.repository.UserRepository; import com.medtrack.warehouse.entity.*; import com.medtrack.warehouse.repository.WarehouseRepository; import jakarta.persistence.EntityManager; import java.time.Year; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*;
@Service public class TransferService {private final StockTransferRepository transfers;private final MedicineRepository medicines;private final WarehouseRepository warehouses;private final UserRepository users;private final FefoAllocationEngine fefo;private final EntityManager em; public TransferService(StockTransferRepository t,MedicineRepository m,WarehouseRepository w,UserRepository u,FefoAllocationEngine f,EntityManager e){transfers=t;medicines=m;warehouses=w;users=u;fefo=f;em=e;}@Transactional public TransferResponse create(UUID actorId,TransferRequest r){User actor=user(actorId);Warehouse source=actor.getAssignedWarehouse();if(source==null||source.getStatus()!=WarehouseStatus.ACTIVE)throw new DomainException("SOURCE_WAREHOUSE_REQUIRED","An active assigned warehouse is required");Warehouse dest=warehouse(r.destinationWarehouseId());if(source.getId().equals(dest.getId()))throw new DomainException("TRANSFER_WAREHOUSE_MATCH","Source and destination must differ");if(!"STORE_MANAGER".equals(actor.getRole().getName())&&!"CENTRAL_WAREHOUSE_MANAGER".equals(actor.getRole().getName())&&!"SUPER_ADMIN".equals(actor.getRole().getName()))throw new ConflictException("TRANSFER_REQUEST_NOT_ALLOWED","User cannot request transfers");StockTransfer t=new StockTransfer(number(),source,dest,actor,r.notes());for(TransferRequest.Item item:r.items()){Medicine m=medicines.findById(item.medicineId()).orElseThrow(()->new NotFoundException("Medicine"));if(m.getStatus()!=MedicineStatus.ACTIVE)throw new DomainException("MEDICINE_DISCONTINUED","Discontinued medicine cannot be requested");t.addItem(new StockTransferItem(m,item.quantity()));}return TransferResponse.of(transfers.save(t));}@Transactional public TransferResponse approve(UUID actorId,UUID id){StockTransfer t=lock(id);if(!"SUPER_ADMIN".equals(user(actorId).getRole().getName())&&!"CENTRAL_WAREHOUSE_MANAGER".equals(user(actorId).getRole().getName()))throw new ConflictException("TRANSFER_APPROVAL_NOT_ALLOWED","User cannot approve transfers");t.approve(user(actorId));return TransferResponse.of(t);}@Transactional public TransferResponse allocate(UUID actorId,UUID id){StockTransfer t=lock(id);t.transition(TransferStatus.ALLOCATED);for(StockTransferItem requested:t.getItems().stream().filter(i->i.getBatch()==null).toList()){FefoAllocationResponse a=fefo.allocate(actorId,new FefoAllocationRequest(requested.getMedicine().getId(),t.getSourceWarehouse().getId(),requested.getRequestedQuantity()));for(FefoAllocationResponse.Allocation x:a.allocations()){com.medtrack.batch.entity.Batch b=em.getReference(com.medtrack.batch.entity.Batch.class,x.batchId());t.addItem(new StockTransferItem(requested.getMedicine(),b,x.quantity()));}}return TransferResponse.of(t);}@Transactional public TransferResponse pick(UUID actorId,UUID id,PickRequest r){StockTransfer t=lock(id);t.transition(TransferStatus.PICKED);for(PickRequest.Item item:r.items()){StockTransferItem match=t.getItems().stream().filter(i->i.getBatch()!=null&&i.getBatch().getId().equals(item.batchId())).findFirst().orElseThrow(()->new DomainException("UNALLOCATED_BATCH","Picked batch was not allocated"));try{match.pick(item.quantity());}catch(IllegalArgumentException e){throw new DomainException("INVALID_PICK_QUANTITY",e.getMessage());}}if(t.getItems().stream().filter(i->i.getBatch()!=null).anyMatch(i->i.getPickedQuantity()!=i.getAllocatedQuantity()))throw new DomainException("INCOMPLETE_PICK","All allocated batches must be picked");return TransferResponse.of(t);}@Transactional public TransferResponse pack(UUID id){StockTransfer t=lock(id);t.transition(TransferStatus.PACKED);return TransferResponse.of(t);}public StockTransfer locked(UUID id){return lock(id);}private StockTransfer lock(UUID id){return transfers.lockById(id).orElseThrow(()->new NotFoundException("Stock transfer"));}private User user(UUID id){return users.findById(id).orElseThrow(()->new NotFoundException("User"));}private Warehouse warehouse(UUID id){Warehouse w=warehouses.findById(id).orElseThrow(()->new NotFoundException("Warehouse"));if(w.getStatus()!=WarehouseStatus.ACTIVE)throw new DomainException("WAREHOUSE_INACTIVE","Warehouse is inactive");return w;}private String number(){Number n=(Number)em.createNativeQuery("select nextval('medtrack_transfer_number_seq')").getSingleResult();return "TRF-"+Year.now().getValue()+"-%06d".formatted(n.longValue());}}
